-- Release 0.2 — Email notifications for accounts, deals and tasks.
--
-- Built on the existing notification system (20260803091000 and
-- 20260803093000), not beside it: the same notifications table feeds the same
-- bell, and the same notify-email drain sends the mail. What 0.2 adds:
--
--   * Accounts and deals notify: assigned (to the new owner), closed (deal won
--     or lost, account archived) to the owner and watchers.
--   * Due and overdue: once on a task's due date or a deal's next-action date,
--     and once more the day after if it is still open. Generated by
--     notification_enqueue_due(), which the notify-email function runs daily.
--   * Two more email switches: due/overdue and closed.
--
-- Recipients. A record's owner — account/deal owner_id, a task's assignee or,
-- unassigned, its author — plus its watchers. Watching stays self-service
-- (task_watchers, account_watchers, deal_watchers all pin user_id to the
-- caller).
--
-- Email. The existing rule stands for everything except one case: email is
-- opt-in (email_enabled defaults to false) and per-type switches narrow it.
-- The exception is a due or overdue reminder addressed to the record's OWNER,
-- which is always emailed. 0.2's promise is that no task or deal passes its
-- date without an email reaching its owner, and an opt-in default would break
-- that promise for everyone who never opened Settings. Owners cannot
-- unsubscribe from their own records; watchers can, by unwatching.
--
-- Nobody is told about their own action — same as the task trigger.

-- ============================================================
-- notifications: new types, record pointers, idempotency key
-- ============================================================

ALTER TABLE public.notifications
  DROP CONSTRAINT IF EXISTS notifications_type_check;

ALTER TABLE public.notifications
  ADD CONSTRAINT notifications_type_check CHECK (
    type IN (
      'task_assigned', 'task_unassigned', 'task_updated',
      'task_completed', 'task_reopened',
      'mention', 'channel_message', 'proposal_pending', 'proposal_decided',
      'task_due', 'task_overdue',
      'deal_assigned', 'deal_due', 'deal_overdue', 'deal_closed',
      'account_assigned', 'account_archived'
    )
  );

ALTER TABLE public.notifications
  ADD COLUMN deal_id UUID REFERENCES public.deals(id) ON DELETE CASCADE,
  ADD COLUMN account_id UUID REFERENCES public.accounts(id) ON DELETE CASCADE,
  -- Set only by generated notifications (due / overdue). One per person per
  -- key, so a re-run of the daily job — or two overlapping runs — cannot file
  -- the same reminder twice.
  ADD COLUMN dedupe_key TEXT;

CREATE UNIQUE INDEX notifications_dedupe_idx
ON public.notifications (user_id, dedupe_key)
WHERE dedupe_key IS NOT NULL;

CREATE INDEX notifications_deal_id_idx
ON public.notifications (deal_id) WHERE deal_id IS NOT NULL;

CREATE INDEX notifications_account_id_idx
ON public.notifications (account_id) WHERE account_id IS NOT NULL;

-- ============================================================
-- notification_preferences: due and closed switches
-- ============================================================

ALTER TABLE public.notification_preferences
  ADD COLUMN email_on_due BOOLEAN NOT NULL DEFAULT true,
  ADD COLUMN email_on_closed BOOLEAN NOT NULL DEFAULT true;

GRANT UPDATE (email_on_due, email_on_closed)
ON public.notification_preferences TO authenticated;

-- ============================================================
-- enqueue_notification — the generic fan-out
-- ============================================================
-- enqueue_task_notification() stays as it is for the task trigger. This is the
-- same logic for any record, with two additions: a dedupe key, and an owner
-- who is always emailed (p_always_email_to).

CREATE OR REPLACE FUNCTION public.enqueue_notification(
  p_user_ids UUID[],
  p_type TEXT,
  p_title TEXT,
  p_body TEXT,
  p_actor UUID,
  p_task_id UUID DEFAULT NULL,
  p_product_id UUID DEFAULT NULL,
  p_deal_id UUID DEFAULT NULL,
  p_account_id UUID DEFAULT NULL,
  p_dedupe_key TEXT DEFAULT NULL,
  p_always_email_to UUID DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  inserted INTEGER;
BEGIN
  WITH recipients AS (
    SELECT DISTINCT u AS user_id
    FROM unnest(p_user_ids) AS u
    JOIN public.team_members tm
      ON tm.user_id = u AND tm.is_active AND tm.kind = 'human'
    WHERE u IS NOT NULL
      AND (p_actor IS NULL OR u <> p_actor)
  )
  INSERT INTO public.notifications (
    user_id, type, task_id, product_id, deal_id, account_id, actor_id,
    title, body, dedupe_key, email_state
  )
  SELECT
    r.user_id, p_type, p_task_id, p_product_id, p_deal_id, p_account_id, p_actor,
    left(p_title, 300), left(p_body, 2000), p_dedupe_key,
    CASE
      WHEN r.user_id = p_always_email_to THEN 'pending'
      WHEN coalesce(np.email_enabled, false) AND CASE
        WHEN p_type IN ('task_assigned', 'deal_assigned', 'account_assigned')
          THEN coalesce(np.email_on_assign, true)
        WHEN p_type IN ('task_due', 'task_overdue', 'deal_due', 'deal_overdue')
          THEN coalesce(np.email_on_due, true)
        WHEN p_type IN ('task_completed', 'deal_closed', 'account_archived')
          THEN coalesce(np.email_on_closed, true)
        ELSE coalesce(np.email_on_update, true)
      END THEN 'pending'
      ELSE 'skipped'
    END
  FROM recipients r
  LEFT JOIN public.notification_preferences np ON np.user_id = r.user_id
  ON CONFLICT (user_id, dedupe_key) WHERE dedupe_key IS NOT NULL DO NOTHING;

  GET DIAGNOSTICS inserted = ROW_COUNT;
  RETURN inserted;
END;
$$;

-- SECURITY DEFINER and it writes rows clients may not insert: without this,
-- any signed-in user could forge a notification (see the same note on
-- enqueue_task_notification).
REVOKE ALL ON FUNCTION public.enqueue_notification(
  UUID[], TEXT, TEXT, TEXT, UUID, UUID, UUID, UUID, UUID, TEXT, UUID
) FROM PUBLIC, anon, authenticated;

-- ============================================================
-- Deal and account triggers
-- ============================================================

CREATE OR REPLACE FUNCTION public.deals_notify()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  actor UUID := (SELECT auth.uid());
  actor_name TEXT;
  account_name TEXT;
  watchers UUID[];
BEGIN
  SELECT display_name INTO actor_name FROM public.team_members WHERE user_id = actor;
  actor_name := coalesce(actor_name, 'Someone');
  SELECT name INTO account_name FROM public.accounts WHERE id = NEW.account_id;

  IF TG_OP = 'INSERT' OR NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    PERFORM public.enqueue_notification(
      ARRAY[NEW.owner_id], 'deal_assigned', NEW.name,
      actor_name || ' made you the owner of a deal with ' || coalesce(account_name, 'an account'),
      actor, NULL, NEW.product_id, NEW.id, NEW.account_id
    );
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.stage IN ('closed_won', 'closed_lost')
     AND NEW.stage IS DISTINCT FROM OLD.stage THEN
    SELECT coalesce(array_agg(user_id), ARRAY[]::UUID[]) INTO watchers
    FROM public.deal_watchers WHERE deal_id = NEW.id;

    PERFORM public.enqueue_notification(
      NEW.owner_id || watchers, 'deal_closed', NEW.name,
      actor_name || CASE
        WHEN NEW.stage = 'closed_won' THEN ' closed this deal as won'
        ELSE ' closed this deal as lost: ' || coalesce(NEW.close_reason, '')
      END,
      actor, NULL, NEW.product_id, NEW.id, NEW.account_id
    );
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER deals_notify
AFTER INSERT OR UPDATE OF owner_id, stage ON public.deals
FOR EACH ROW EXECUTE FUNCTION public.deals_notify();

CREATE OR REPLACE FUNCTION public.accounts_notify()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  actor UUID := (SELECT auth.uid());
  actor_name TEXT;
  watchers UUID[];
BEGIN
  SELECT display_name INTO actor_name FROM public.team_members WHERE user_id = actor;
  actor_name := coalesce(actor_name, 'Someone');

  IF TG_OP = 'INSERT' OR NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    PERFORM public.enqueue_notification(
      ARRAY[NEW.owner_id], 'account_assigned', NEW.name,
      actor_name || ' made you the owner of this account',
      actor, NULL, NULL, NULL, NEW.id
    );
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.archived_at IS NOT NULL AND OLD.archived_at IS NULL THEN
    SELECT coalesce(array_agg(user_id), ARRAY[]::UUID[]) INTO watchers
    FROM public.account_watchers WHERE account_id = NEW.id;

    PERFORM public.enqueue_notification(
      NEW.owner_id || watchers, 'account_archived', NEW.name,
      actor_name || ' archived this account',
      actor, NULL, NULL, NULL, NEW.id
    );
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER accounts_notify
AFTER INSERT OR UPDATE OF owner_id, archived_at ON public.accounts
FOR EACH ROW EXECUTE FUNCTION public.accounts_notify();

-- ============================================================
-- Due and overdue — generated daily
-- ============================================================
-- Due: the date is today (Kuwait calendar). Overdue: it passed and the record
-- is still open — keyed by the date, so it fires once per date. The three-day
-- look-back means a missed daily run is caught up the next day rather than
-- lost; the dedupe key keeps the catch-up from repeating anything.
--
-- Called by functions/notify-email.ts in its daily mode through the admin
-- client, which is the only caller: EXECUTE is revoked from client roles.

CREATE OR REPLACE FUNCTION public.notification_enqueue_due(
  p_today DATE DEFAULT public.business_today()
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  r RECORD;
  owner UUID;
  watchers UUID[];
  kind TEXT;
  total INTEGER := 0;
BEGIN
  FOR r IN
    SELECT t.id, t.title, t.product_id, t.due_date, t.assignee_id, t.created_by,
           p.name AS product_name
    FROM public.product_tasks t
    LEFT JOIN public.products p ON p.id = t.product_id
    WHERE t.status = 'pending'
      AND t.due_date BETWEEN p_today - 3 AND p_today
  LOOP
    owner := coalesce(r.assignee_id, r.created_by);
    kind := CASE WHEN r.due_date = p_today THEN 'task_due' ELSE 'task_overdue' END;
    SELECT coalesce(array_agg(user_id), ARRAY[]::UUID[]) INTO watchers
    FROM public.task_watchers WHERE task_id = r.id;

    total := total + public.enqueue_notification(
      owner || watchers, kind, r.title,
      CASE WHEN kind = 'task_due'
        THEN 'Due today'
        ELSE 'Overdue since ' || to_char(r.due_date, 'DD Mon YYYY')
      END || coalesce(' · ' || r.product_name, ''),
      NULL, r.id, r.product_id, NULL, NULL,
      kind || ':' || r.due_date, owner
    );
  END LOOP;

  FOR r IN
    SELECT d.id, d.name, d.product_id, d.account_id, d.owner_id,
           d.next_action, d.next_action_date, a.name AS account_name
    FROM public.deals d
    JOIN public.accounts a ON a.id = d.account_id
    WHERE d.stage NOT IN ('closed_won', 'closed_lost')
      AND d.next_action_date BETWEEN p_today - 3 AND p_today
  LOOP
    kind := CASE WHEN r.next_action_date = p_today THEN 'deal_due' ELSE 'deal_overdue' END;
    SELECT coalesce(array_agg(user_id), ARRAY[]::UUID[]) INTO watchers
    FROM public.deal_watchers WHERE deal_id = r.id;

    total := total + public.enqueue_notification(
      r.owner_id || watchers, kind, r.name,
      CASE WHEN kind = 'deal_due'
        THEN 'Next action due today'
        ELSE 'Next action overdue since ' || to_char(r.next_action_date, 'DD Mon YYYY')
      END || coalesce(': ' || r.next_action, '') || ' · ' || r.account_name,
      NULL, NULL, r.product_id, r.id, r.account_id,
      kind || ':' || r.next_action_date, r.owner_id
    );
  END LOOP;

  RETURN total;
END;
$$;

REVOKE ALL ON FUNCTION public.notification_enqueue_due(DATE)
FROM PUBLIC, anon, authenticated;
